WITH parsed AS (SELECT id, plan, effective_from, tier_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT plan, COUNT(CASE WHEN plan = 'enterprise' THEN 1 END) AS enterprise_count, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(plan = 'starter') AS starter_events, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, COUNT(*) AS cnt FROM parsed GROUP BY plan
